    /// `Diligent_GetEngineFactoryD3D12()` must return a non-null factory.
    #[test]
    fn factory_d3d12_resolves() {
        let factory = EngineFactoryD3D12::d3d12();
        assert!(factory.is_ok(), "factory creation failed: {:?}", factory.err());
    }

    /// Factory -> device + context creation must succeed and the device
    /// must report `RENDER_DEVICE_TYPE_D3D12`.
    #[test]
    fn device_and_context_create_as_d3d12() {
        let factory = EngineFactoryD3D12::d3d12().expect("factory");
        let (device, _context) = factory
            .create_device_and_contexts()
            .expect("device+context creation");
        let info = device.device_info();
        assert_eq!(
            info.Type,
            diligent_sys::bindings::RENDER_DEVICE_TYPE::RENDER_DEVICE_TYPE_D3D12,
            "device type is not D3D12"
        );
    }

    /// `create_swap_chain` with a null `hwnd` must return `Err` without
    /// crashing (error-path smoke).
    #[test]
    fn swap_chain_null_hwnd_fails() {
        let factory = EngineFactoryD3D12::d3d12().expect("factory");
        let (device, context) = factory
            .create_device_and_contexts()
            .expect("device+context");
        let result = factory.create_swap_chain(&device, &context, std::ptr::null_mut(), 640, 480);
        assert!(result.is_err(), "null hwnd should have failed");
    }

    /// Create-and-drop cycle must not crash or leak (run several iterations
    /// to exercise ref-count churn).
    #[test]
    fn create_drop_cycle_is_safe() {
        for _ in 0..3 {
            let factory = EngineFactoryD3D12::d3d12().expect("factory");
            let (device, context) = factory
                .create_device_and_contexts()
                .expect("device+context");
            drop(context);
            drop(device);
            drop(factory);
        }
    }

    /// `Handle::add_ref` shares one engine object between several handles;
    /// dropping them in any order must not double-free (reference counting
    /// verified through the engine's own counter).
    #[test]
    fn handle_add_ref_shared_ownership_does_not_double_free() {
        let factory = EngineFactoryD3D12::d3d12().expect("factory");
        let (device, _context) = factory
            .create_device_and_contexts()
            .expect("device+context");

        let buffer = device
            .create_buffer(
                "add_ref_test",
                16,
                diligent_sys::bindings::_BIND_FLAGS::BIND_UNIFORM_BUFFER
                    as diligent_sys::bindings::BIND_FLAGS,
                diligent_sys::bindings::_USAGE::USAGE_DEFAULT
                    as diligent_sys::bindings::USAGE,
                0,
                None,
            )
            .expect("buffer");

        for _ in 0..3 {
            let h1 = buffer.add_ref();
            let h2 = h1.add_ref();
            assert_eq!(h2.strong_ref_count(), 3, "two add_refs, three owners");
            drop(h1);
            assert_eq!(h2.strong_ref_count(), 2);
            drop(h2);
            assert_eq!(buffer.strong_ref_count(), 1);
        }
        drop(buffer);
    }

    /// Texture creation (with initial data), default-view borrow and an
    /// owned view with an sRGB format override (the dual-view path).
    #[test]
    fn texture_creation_smoke() {
        use diligent_sys::bindings as sys;
        let factory = EngineFactoryD3D12::d3d12().expect("factory");
        let (device, _context) = factory
            .create_device_and_contexts()
            .expect("device+context");

        let data = [0u8; 4 * 4 * 4]; // 4x4 Rgba8
        let texture = device
            .create_texture(
                "texture_smoke",
                4,
                4,
                1,
                1,
                sys::_TEXTURE_FORMAT::TEX_FORMAT_RGBA8_UNORM as sys::TEXTURE_FORMAT,
                sys::_BIND_FLAGS::BIND_SHADER_RESOURCE as sys::BIND_FLAGS,
                sys::_USAGE::USAGE_IMMUTABLE as sys::USAGE,
                1,
                Some(&data),
            )
            .expect("texture");

        let default_srv = texture
            .get_default_view(sys::_TEXTURE_VIEW_TYPE::TEXTURE_VIEW_SHADER_RESOURCE as sys::TEXTURE_VIEW_TYPE)
            .expect("default SRV");
        assert!(!default_srv.as_ptr().is_null());

        // sRGB dual view: same texture, format overridden in the view desc.
        let srv_desc = desc::texture_view(
            sys::_TEXTURE_VIEW_TYPE::TEXTURE_VIEW_SHADER_RESOURCE as sys::TEXTURE_VIEW_TYPE,
            Some(sys::_TEXTURE_FORMAT::TEX_FORMAT_RGBA8_UNORM_SRGB as sys::TEXTURE_FORMAT),
            0,
            1,
            0,
            1,
        );
        let srgb_view = device
            .create_texture_view(&texture, &srv_desc)
            .expect("sRGB view over linear texture");
        assert!(!srgb_view.as_raw().is_null());
        drop(srgb_view);
        drop(texture);
    }

