    /// Regression: initial data must match the subresource size exactly.
    /// `TextureSubResData` has no size field - the engine copies
    /// `Stride x Height` bytes unconditionally, so a shorter slice would be
    /// read out of bounds. The wrapper must reject it before the engine.
    #[test]
    fn texture_initial_data_length_is_validated() {
        use diligent_sys::bindings as sys;
        let factory = EngineFactoryD3D12::d3d12().expect("factory");
        let (device, _context) = factory
            .create_device_and_contexts()
            .expect("device+context");

        // 2x2 RGBA8: one subresource is exactly 16 bytes.
        let exact = [0u8; 16];
        let short = [0u8; 15];

        let too_short = device.create_texture(
            "texture_too_short",
            2,
            2,
            1,
            1,
            sys::_TEXTURE_FORMAT::TEX_FORMAT_RGBA8_UNORM as sys::TEXTURE_FORMAT,
            sys::_BIND_FLAGS::BIND_SHADER_RESOURCE as sys::BIND_FLAGS,
            sys::_USAGE::USAGE_IMMUTABLE as sys::USAGE,
            1,
            Some(&short),
        );
        assert!(
            too_short.is_err(),
            "initial data shorter than the subresource must be rejected"
        );

        let exact_len = device.create_texture(
            "texture_exact_len",
            2,
            2,
            1,
            1,
            sys::_TEXTURE_FORMAT::TEX_FORMAT_RGBA8_UNORM as sys::TEXTURE_FORMAT,
            sys::_BIND_FLAGS::BIND_SHADER_RESOURCE as sys::BIND_FLAGS,
            sys::_USAGE::USAGE_IMMUTABLE as sys::USAGE,
            1,
            Some(&exact),
        );
        assert!(
            exact_len.is_ok(),
            "exact-length initial data must be accepted: {:?}",
            exact_len.err()
        );
    }

    /// Sampler creation, both linear and anisotropic flavors; the aniso
    /// guard must reject mixed filters.
    #[test]
    fn sampler_creation_smoke() {
        use diligent_sys::bindings as sys;
        let factory = EngineFactoryD3D12::d3d12().expect("factory");
        let (device, _context) = factory
            .create_device_and_contexts()
            .expect("device+context");

        let linear = desc::sampler(
            sys::_FILTER_TYPE::FILTER_TYPE_LINEAR as sys::FILTER_TYPE,
            sys::_FILTER_TYPE::FILTER_TYPE_LINEAR as sys::FILTER_TYPE,
            sys::_FILTER_TYPE::FILTER_TYPE_LINEAR as sys::FILTER_TYPE,
            sys::_TEXTURE_ADDRESS_MODE::TEXTURE_ADDRESS_WRAP as sys::TEXTURE_ADDRESS_MODE,
            sys::_TEXTURE_ADDRESS_MODE::TEXTURE_ADDRESS_WRAP as sys::TEXTURE_ADDRESS_MODE,
            sys::_TEXTURE_ADDRESS_MODE::TEXTURE_ADDRESS_WRAP as sys::TEXTURE_ADDRESS_MODE,
            None,
            0,
            0.0,
            f32::MAX,
        );
        let sampler = device
            .create_sampler("sampler_linear", &linear)
            .expect("linear sampler");
        drop(sampler);

        let aniso = desc::sampler(
            sys::_FILTER_TYPE::FILTER_TYPE_ANISOTROPIC as sys::FILTER_TYPE,
            sys::_FILTER_TYPE::FILTER_TYPE_ANISOTROPIC as sys::FILTER_TYPE,
            sys::_FILTER_TYPE::FILTER_TYPE_ANISOTROPIC as sys::FILTER_TYPE,
            sys::_TEXTURE_ADDRESS_MODE::TEXTURE_ADDRESS_CLAMP as sys::TEXTURE_ADDRESS_MODE,
            sys::_TEXTURE_ADDRESS_MODE::TEXTURE_ADDRESS_CLAMP as sys::TEXTURE_ADDRESS_MODE,
            sys::_TEXTURE_ADDRESS_MODE::TEXTURE_ADDRESS_CLAMP as sys::TEXTURE_ADDRESS_MODE,
            None,
            16,
            0.0,
            f32::MAX,
        );
        let sampler = device
            .create_sampler("sampler_aniso", &aniso)
            .expect("anisotropic sampler");
        drop(sampler);

        let mixed = desc::sampler(
            sys::_FILTER_TYPE::FILTER_TYPE_LINEAR as sys::FILTER_TYPE,
            sys::_FILTER_TYPE::FILTER_TYPE_ANISOTROPIC as sys::FILTER_TYPE,
            sys::_FILTER_TYPE::FILTER_TYPE_LINEAR as sys::FILTER_TYPE,
            sys::_TEXTURE_ADDRESS_MODE::TEXTURE_ADDRESS_WRAP as sys::TEXTURE_ADDRESS_MODE,
            sys::_TEXTURE_ADDRESS_MODE::TEXTURE_ADDRESS_WRAP as sys::TEXTURE_ADDRESS_MODE,
            sys::_TEXTURE_ADDRESS_MODE::TEXTURE_ADDRESS_WRAP as sys::TEXTURE_ADDRESS_MODE,
            None,
            8,
            0.0,
            f32::MAX,
        );
        assert!(
            device.create_sampler("sampler_mixed", &mixed).is_err(),
            "anisotropy with mixed filters must be rejected"
        );
    }

